// ─────────────────────────────────────────────
// LORE — Golden eval cases
//
// Every SOP excerpt below is copied from the mock AMM documents in
// docs/sops (generated by generate-sops.py). Every oral note is copied
// from data/marc-knowledge.json. Nothing here is invented — the case
// set cannot assert "no fabricated measurements" while fabricating its
// own thresholds.
// ─────────────────────────────────────────────

import type { EvalContext } from "./graders";

export type EvalCase = {
    id: string;
    category: string;
    /** Drives whether the AMM closing sentence is expected. */
    intent: "maintenance" | "project";
    question: string;
    context: EvalContext;
    expect: {
        disclaimer: boolean;
        sopFirst?: boolean;
        attribution?: boolean;
        noFabrication?: boolean;
        abstain?: boolean;
        forbidden?: RegExp[];
        required?: RegExp[];
    };
    note?: string;
};

// ── SOP excerpts (verbatim from docs/sops) ───

const SOP_VIB_BANDS = `AMM 72-21-00 — Fan Vibration Monitoring, severity classification.
N1 vibration is displayed in N1 Vibration Units (NU) on the EVMU readout.
NORMAL: < 2.0 NU — no action required. Continuous monitoring by on-board systems.
MONITOR: 2.0 - 3.5 NU — record reading. Monitor 3 flight cycles. Visual inspection of the fan section.
ESCALATE: > 3.5 NU — immediate action. Do not dispatch. Detailed inspection.`;

const SOP_VIB_COLD = `AMM 72-21-00 — Fan Vibration Monitoring, ambient temperature effects.
At low ambient temperatures (T < 8 deg C), a temporary increase in N1 vibration up to 2.5 NU may occur due to fan blade root stiffness changes. If vibration returns to < 2.0 NU after the engine has warmed up, no maintenance action is required.`;

const SOP_COLD_OPS = `AMM 72-00-00-810-001 — Cold Weather Operations, N1 vibration.
At ambient temperatures below 8 deg C the following is expected and considered NORMAL: a temporary increase in N1 vibration of up to 0.5 NU above the warm-weather baseline for the specific engine serial number.
CRITICAL: this cold-weather vibration increase is a known characteristic, not a defect. If the vibration returns to normal (< 2.0 NU) after engine warm-up (oil temperature > 50 deg C), no maintenance action is required. Do NOT initiate a fan trim balance or escalation procedure for cold-weather vibration alone.
Trigger for further action: if N1 vibration exceeds 2.5 NU in cold conditions, OR if vibration does NOT return to baseline after warm-up, follow the standard troubleshooting procedure in AMM 72-21-00.`;

const SOP_ESCALATION = `AMM 72-21-00 — Escalation procedure.
If vibration exceeds 3.5 NU, or if the MONITOR level persists for more than 3 consecutive flight cycles, the escalation procedure is mandatory.
A fan trim balance must be performed in accordance with AMM 72-21-00-720-001. After balance weight installation, vibration levels must be reduced to below 2.0 NU.
If vibration remains > 3.5 NU after trim balance, perform a full borescope inspection of the fan and booster stages per AMM 72-21-10.`;

const SOP_GROUND_RUN = `AMM 72-00-00 — General Engine Maintenance, ground run.
Stabilise at idle for minimum 3 minutes. Record N1, N2, EGT, oil pressure, oil temperature, vibration.
Advance to 80% N1. Hold for 30 seconds. Record the same parameters.
Acceptance: N1 vibration < 2.0 NU at idle and < 2.0 NU at 80% N1. Oil consumption < 0.4 qt/hr.`;

const SOP_OIL = `AMM 72-53-00 — Oil System Servicing, oil consumption monitoring.
Normal oil consumption for the CFM56-5B is 0.10 - 0.30 US quarts per flight hour.
< 0.30 qt/hr — NORMAL. No action. Record in trend log.
0.30 - 0.50 qt/hr — ELEVATED. Increase monitoring to every flight. Check for leaks.
> 0.50 qt/hr — EXCESSIVE. Do not dispatch. Investigate.
Consumption must be tracked over a rolling 50 flight-hour window. A sudden increase of more than 0.10 qt/hr from the established baseline requires investigation, even if the absolute rate is within NORMAL range.`;

const SOP_OIL_DRAIN = `AMM 72-53-00 — Oil System Servicing, mast drain.
A slight oil film on the mast drain outlet is normal. A steady drip or streak exceeding 50 mm from the drain requires further investigation per AMM 72-53-00.`;

const SOP_BORESCOPE_LIMITS = `AMM 72-21-10 — Borescope Inspection, findings and limits.
Fan blade tip rub: depth < 1.0 mm — blend per AMM 72-21-11.
Leading edge nick: depth < 2.0 mm and length < 10 mm — blend per AMM 72-21-11.
Abradable rub depth: < 1.5 mm — contact Engineering.
Booster blade nick: depth < 0.5 mm — blend if accessible.
Equipment: video borescope with minimum 6 mm probe diameter and 1.5 m working length.`;

const SOP_BLADE_ZONES = `AMM 72-21-11 — Fan Blade Damage Limits, damage limits by blade zone.
Zone A (Tip), outer 25% of blade span: 3.0 mm nick, 5.0 mm dent.
Zone B (Mid), 25-75% of blade span: 2.0 mm nick, 3.0 mm dent.
Zone C (Root), inner 25% of blade span: 1.0 mm nick, 1.5 mm dent.
Zone LE (Leading edge, all spans): 2.0 mm nick, 2.5 mm dent.
Zone TE (Trailing edge, all spans): 1.5 mm nick, 2.0 mm dent.
Maximum total material removal per blade: 8.0 mm cumulative depth across all blends.`;

const SOP_CHIP_DETECTOR = `AMM 72-53-00 — Oil System Servicing, magnetic chip detector.
Fine fuzz (< 1 mm particles): clean and reinstall. Monitor.
Flakes or chips (> 1 mm): contact Engineering. May indicate bearing distress.`;

const SOP_ANTI_ICE = `AMM 72-00-00-810-001 — Cold Weather Operations, engine anti-ice.
Do not operate engine anti-ice on the ground for extended periods (> 10 minutes) with engines at idle. This can cause thermal stress to the inlet cowl.
If ground hold exceeds 10 minutes in icing conditions, increase thrust to 50% N1 periodically (30 seconds every 5 minutes) to maintain airflow.`;

// ── Oral knowledge (verbatim from data/marc-knowledge.json) ──

const ORAL_VIB_COLD = `Marc Delaunay, 2025-10-14, F-GKXA, CFM56-5B fan section, cold weather T < 8 deg C:
"F-GKXA shows N1 harmonic resonance 2-3 units in cold weather below 8 deg C. This is a known characteristic of this specific airframe, not a defect. I've seen it 4 times in 8 years. Monitor across 2 cycles before escalating. Do not ground the aircraft for this alone."`;

const ORAL_HPC_EROSION = `Marc Delaunay, 2025-08-22, F-GKXA, CFM56-5B HP compressor, standard conditions:
"Blade inspection on F-GKXA HPC stage 3: slight leading edge erosion, within limits. Mark for tracking every 200 cycles. This airframe tends to show erosion earlier than fleet average due to its route pattern through coastal environments."`;

const ORAL_OIL = `Marc Delaunay, 2025-06-10, F-GKXA, CFM56-5B oil system, after long haul:
"F-GKXA oil consumption runs slightly higher than fleet average — about 0.3 qt/hr vs 0.2 qt/hr typical. This has been stable for 3 years. It's within limits. Don't flag it as trending unless it exceeds 0.4 qt/hr."`;

const ORAL_BLADE_7 = `Marc Delaunay, 2025-04-18, F-GHQJ, CFM56-5B fan section, standard conditions:
"F-GHQJ fan blade #7 was replaced 400 cycles ago. The new blade has a slightly different vibration signature during high power settings. This is normal for replacement blades and settles after ~500 cycles. No action needed."`;

const ORAL_FMU = `Marc Delaunay, 2025-03-05, F-GHQJ, CFM56-5B fuel system, hot weather T > 35 deg C:
"F-GHQJ has a known fuel metering unit delay on hot starts above 35 deg C. Takes about 2 extra seconds to stabilize. It's a characteristic of the older FMU variant installed. Within all limits but worth noting for new technicians who might mistake it for a malfunction."`;

const ORAL_GEARBOX = `Marc Delaunay, 2025-01-20, F-GKXA, CFM56-5B gearbox, cold start:
"F-GKXA accessory gearbox makes a brief whine during first start of the day in winter. Lasts about 15 seconds then disappears. It's the accessory gearbox oil warming up. Completely normal. I've monitored this for 5 winters. No degradation trend."`;

